parameters.jsCode:
// Fetch all items from the current AI node and the upstream qualification matrix dynamically
const geminiItems = $input.all();
const initialEngineItems = $('Lead Qualification Matrix').all();

return geminiItems.map((item, index) => {
  // Dynamically match upstream lead data by index, falling back to current item json if out of sync
  const prevData = initialEngineItems[index]?.json || item.json || {};

  const firstName = prevData.firstName || '';
  const lastName = prevData.lastName || '';
  const email = prevData.email || '';
  const phone = prevData.phone || '';
  const company = prevData.company || '';
  const budgetStr = prevData.budget || '';
  const numericBudget = prevData.numericBudget || 0;
  const notesText = prevData.notes || '';
  const hasUrgentKeyword = prevData.urgency_detected === 'YES';

  // Start with the score calculated in the previous node
  let clampedScore = prevData.final_score || 0;

  // Dynamically extract the AI output object whether it's nested or flat
  const aiOutput = item.json.output || item.json;
  const rawIntent = aiOutput.intent || aiOutput.ai_intent || item.json.intent || 'Exploring';
  const rawSummary = aiOutput.summary || aiOutput.ai_summary || item.json.summary || '';

  // Normalize intent dynamically to match downstream routing keys strictly
  let normalizedIntent = 'Exploring';
  const intentStr = String(rawIntent).toLowerCase();

  if (intentStr.includes('buying') || intentStr.includes('immediate') || intentStr.includes('hot') || intentStr.includes('urgent')) {
    normalizedIntent = 'Immediate Buying';
  } else if (intentStr.includes('support')) {
    normalizedIntent = 'Support';
  } else if (intentStr.includes('spam')) {
    normalizedIntent = 'Spam';
  }

  // Apply AI Intent Bonus dynamically if Immediate Buying is detected
  if (normalizedIntent === 'Immediate Buying' && clampedScore < 100) {
    clampedScore = Math.min(100, clampedScore + 10);
  }

  return {
    json: {
      firstName: firstName,
      lastName: lastName,
      email: email,
      phone: phone,
      company: company,
      budget: budgetStr,
      numericBudget: numericBudget,
      notes: notesText,
      final_score: clampedScore,
      lead_tier: clampedScore >= 70 ? 'HOT' : 'WARM/COLD',
      urgency_detected: hasUrgentKeyword ? 'YES' : 'NO',
      ai_intent: normalizedIntent, // Dynamically mapped and normalized
      ai_summary: typeof rawSummary === 'object' ? JSON.stringify(rawSummary) : String(rawSummary)
    }
  };
});

